mapper.select:
select ex.Ex_Name as exName, ex.Ex_Id_Type as exIdType, ex.Ex_Id_Number as exIdNumber, sec.Sec_Name as secName, pro.P_Name as pName, pro.P_Code as pCode, mn.* from Sec_Expert_Appeal mn left join Sec_Expert ex on ex.Ex_Id=mn.Ex_Id left join Pre_Project pro on pro.P_Id=mn.P_Id left join Sec_Info sec on mn.Sec_Id=sec.Sec_Id ${params.authSql}
and mn.Te_Id = #{params.teId}
and mn.State=#{params.state}
and INSTR(mn.Create_Uname,#{params.createUname})
and INSTR(sec.Sec_Name,#{params.secName})
and likePname(#{params.pName},pro.P_Id)=true
and INSTR(pro.P_Name,#{params.pName})
and INSTR(pro.P_Code,#{params.pCode})
and INSTR(ex.Ex_Name,#{params.exName})
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Create_Time desc
